document.querySelectorAll('[data-lab="G10-I1"]').forEach(root=>{if(root.dataset.ready)return;root.dataset.ready='1';const q=s=>root.querySelector(s),dist=q('[data-distance]'),tilt=q('[data-tilt]'),mode=q('[data-mode]'),en=root.dataset.language==='en';function draw(){const r=+dist.value,alpha=+tilt.value*Math.PI/180,h=[.1*Math.cos(alpha),.1*Math.sin(alpha)],hd=[-h[0],-h[1]],ha=[r-h[0],-h[1]],cos=(hd[0]*ha[0]+hd[1]*ha[1])/(.1*Math.hypot(...ha)),theta=Math.acos(Math.max(-1,Math.min(1,cos)))*180/Math.PI,near=r<.35,aligned=theta>=150,pass=near&&(mode.value==='distance'||aligned),X=x=>310+850*x,Y=y=>220-850*y,color=pass?'#167d84':'#bd7045';q('[data-distance-value]').textContent=r.toFixed(2)+' nm';q('[data-tilt-value]').textContent=tilt.value+'°';q('[data-plot]').innerHTML=`<rect width="1000" height="420" fill="#f6f5ef"/><line x1="${X(0)}" y1="${Y(0)}" x2="${X(r)}" y2="${Y(0)}" stroke="#a2aaa5" stroke-dasharray="7 6"/><line x1="${X(0)}" y1="${Y(0)}" x2="${X(h[0])}" y2="${Y(h[1])}" stroke="#293b47" stroke-width="6"/><line x1="${X(h[0])}" y1="${Y(h[1])}" x2="${X(r)}" y2="${Y(0)}" stroke="${color}" stroke-width="3" stroke-dasharray="5 5"/><circle cx="${X(0)}" cy="${Y(0)}" r="14" fill="#c75246"/><circle cx="${X(h[0])}" cy="${Y(h[1])}" r="10" fill="#e4e6de" stroke="#293b47"/><circle cx="${X(r)}" cy="${Y(0)}" r="14" fill="#c75246"/><text x="${X(0)-45}" y="${Y(0)+45}" font-size="24">D</text><text x="${X(h[0])-8}" y="${Y(h[1])-22}" font-size="24">H</text><text x="${X(r)+20}" y="${Y(0)+35}" font-size="24">A</text><text x="50" y="52" font-size="25">D–A = ${r.toFixed(2)} nm; D–H–A = ${theta.toFixed(2)}°</text><text x="50" y="380" font-size="22">${en?'Solid line: O–H bond; dashed guides: measured geometry.':'实线为O—H化学键；虚线辅助显示测量几何。'}</text>`;q('[data-feedback]').textContent=(en?'Distance <0.35 nm: ':'距离<0.35 nm：')+(near?(en?'yes':'满足'):(en?'no':'未满足'))+'; '+(en?'angle ≥150°: ':'夹角≥150°：')+(aligned?(en?'yes':'满足'):(en?'no':'未满足'))+'. '+(en?'Selected rule: ':'所选规则：')+(pass?(en?'passes.':'满足。'):(en?'does not pass.':'未满足。'));}dist.addEventListener('input',draw);tilt.addEventListener('input',draw);mode.addEventListener('change',draw);q('[data-reset]').addEventListener('click',()=>{dist.value='.30';tilt.value='0';mode.value='both';draw();});draw();});